{"implementation":"def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, ())
    for i in range(n):
        L = lengths[i]
        S = scores[i]
        for w in range(budget, L-1, -1):
            if dp[w-L] is not None:
                prev = dp[w-L]
                cand = (prev[0] + S, prev[1] - L, prev[2] + (i,))
                if dp[w] is None or (cand[0] > dp[w][0] or (cand[0] == dp[w][0] and cand[1] > dp[w][1]) or (cand[0] == dp[w][0] and cand[1] == dp[w][1] and cand[2] < dp[w][2])):
                    dp[w] = cand
    best = dp[0]
    for w in range(1, budget+1):
        cur = dp[w]
        if cur is not None:
            if best is None or (cur[0] > best[0] or (cur[0] == best[0] and cur[1] > best[1]) or (cur[0] == best[0] and cur[1] == best[1] and cur[2] < best[2])):
                best = cur
    selected_indices = list(best[2])
    tokens_used = -best[1]
    total_score = best[0]
    return {
        "selected_indices": selected_indices,
        "tokens_used": tokens_used,
        "total_score": total_score
    }"}
